1	import { readFileSync } from "node:fs";
2	import { runScenario, type Scenario } from "./claim-office.js";
3	
4	const scenario = JSON.parse(readFileSync(0, "utf8")) as Scenario;
5	
6	process.stdout.write(JSON.stringify(runScenario(scenario)));
7

1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Item {
6	  type: string;
7	  material?: string;
8	  enchantment?: number;
9	  cursed?: boolean;
10	}
11	
12	export interface Damage {
13	  itemType: string;
14	  amount: number;
15	}
16	
17	export interface Incident {
18	  cause: string;
19	  damages: Damage[];
20	}
21	
22	export type Step =
23	  | { op: "quote"; items: Item[] }
24	  | { op: "claim"; policy: number; incident: Incident };
25	
26	export interface Scenario {
27	  customer: Customer;
28	  steps: Step[];
29	}
30	
31	export type StepResult =
32	  | { premium: number }
33	  | { payout: number; remainingCap: number };
34	
35	export interface ScenarioResult {
36	  results: StepResult[];
37	}
38	
39	const PROCESSING_FEE = 5;
40	const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
41	  sword: 100,
42	  amulet: 60,
43	  staff: 80,
44	  potion: 40,
45	  rune: 25,
46	  moonstone: 25,
47	};
48	const FIRST_INSURANCE_RATE = 0.1;
49	
50	// Kept as a separate additive term rather than folded into a `policyBase * 1.1`
51	// factor: that is not float-equivalent (100 * 1.1 === 110.00000000000001), and
52	// the final rounding-up turns the stray ulp into a whole extra gold piece.
53	// Do not "simplify".
54	const firstInsuranceSurcharge = (policyBase: number): number =>
55	  policyBase * FIRST_INSURANCE_RATE;
56	
57	// The MHPCO rounds premiums in its own favour: up.
58	const premiumRoundedInMHPCOsFavour = (premium: number): number =>
59	  Math.ceil(premium);
60	
61	const COMPONENT_BLOCK_SIZE = 3;
62	const COMPONENT_BLOCK_PREMIUM = 60;
63	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
64	
65	const basePremiumOf = (item: Item): number => {
66	  const basePremium = BASE_PREMIUM_BY_TYPE[item.type];
67	  if (basePremium === undefined) {
68	    throw new Error(`${item.type} is not on the MHPCO price list`);
69	  }
70	  return basePremium;
71	};
72	
73	// An unenchanted item may leave `enchantment` unset; absent means level 0.
74	const enchantmentLevelOf = (item: Item): number => item.enchantment ?? 0;
75	
76	// A group is every item of one single type, so a group is always non-empty
77	// and homogeneous — the block rule below relies on both.
78	interface TypeGroup {
79	  type: string;
80	  items: Item[];
81	}
82	
83	const groupByType = (items: Item[]): TypeGroup[] =>
84	  [
85	    ...items.reduce(
86	      (groups, item) =>
87	        groups.set(item.type, [...(groups.get(item.type) ?? []), item]),
88	      new Map<string, Item[]>(),
89	    ),
90	  ].map(([type, groupedItems]) => ({ type, items: groupedItems }));
91	
92	const formsComponentBlock = (group: TypeGroup): boolean =>
93	  group.items.length === COMPONENT_BLOCK_SIZE && COMPONENT_TYPES.has(group.type);
94	
95	const sumOfItemBasePremiums = (items: Item[]): number =>
96	  items.reduce((sum, item) => sum + basePremiumOf(item), 0);
97	
98	const groupBasePremium = (group: TypeGroup): number =>
99	  formsComponentBlock(group)
100	    ? COMPONENT_BLOCK_PREMIUM
101	    : sumOfItemBasePremiums(group.items);
102	
103	const policyBasePremium = (items: Item[]): number =>
104	  groupByType(items).reduce((sum, group) => sum + groupBasePremium(group), 0);
105	
106	const CURSE_SURCHARGE_RATE = 0.5;
107	
108	// Item-specific modifiers are charged on the affected item's own base premium,
109	// unlike the policy-wide modifiers which apply to the sum of all of them.
110	const curseSurcharge = (item: Item): number =>
111	  item.cursed ? basePremiumOf(item) * CURSE_SURCHARGE_RATE : 0;
112	
113	// The surcharge threshold below and the reimbursement threshold further down
114	// are two unrelated rules that happen to share the word "enchantment". They
115	// are named apart on purpose: neither is the general case of the other, and
116	// they are deliberately not the same number.
117	const SURCHARGE_ENCHANTMENT_LEVEL = 5;
118	const SURCHARGE_ENCHANTMENT_RATE = 0.3;
119	
120	const isEnchantedEnoughToSurcharge = (item: Item): boolean =>
121	  enchantmentLevelOf(item) >= SURCHARGE_ENCHANTMENT_LEVEL;
122	
123	const enchantmentSurcharge = (item: Item): number =>
124	  isEnchantedEnoughToSurcharge(item)
125	    ? basePremiumOf(item) * SURCHARGE_ENCHANTMENT_RATE
126	    : 0;
127	
128	const itemSurcharge = (item: Item): number =>
129	  curseSurcharge(item) + enchantmentSurcharge(item);
130	
131	const totalItemSurcharges = (items: Item[]): number =>
132	  items.reduce((sum, item) => sum + itemSurcharge(item), 0);
133	
134	const LOYALTY_YEARS = 2;
135	const LOYALTY_DISCOUNT_RATE = 0.2;
136	
137	const loyaltyDiscount = (customer: Customer, policyBase: number): number =>
138	  customer.yearsWithMHPCO >= LOYALTY_YEARS
139	    ? policyBase * LOYALTY_DISCOUNT_RATE
140	    : 0;
141	
142	const FOLLOW_UP_DISCOUNT_RATE = 0.15;
143	
144	// Every contract after the customer's first is a follow-up. Which contract
145	// this is depends on how many quotes preceded it in the scenario, not on the
146	// customer record.
147	const followUpDiscount = (precedingQuotes: number, policyBase: number): number =>
148	  precedingQuotes > 0 ? policyBase * FOLLOW_UP_DISCOUNT_RATE : 0;
149	
150	// Everything a step needs beyond its own payload: who is buying, where in the
151	// scenario the step sits, and the surrounding steps a claim resolves its
152	// `policy` reference against. Bundled so callers thread one named value rather
153	// than a trail of bare parameters.
154	interface StepContext {
155	  customer: Customer;
156	  precedingQuotes: number;
157	  steps: Step[];
158	  // Cap left on each policy that has already been claimed against; a policy
159	  // absent from the map has its full cap available.
160	  remainingCapByPolicy: Map<number, number>;
161	}
162	
163	// Policy-wide modifiers are charged on the sum of all item base premiums,
164	// unlike the item-specific ones above. Each returns a signed adjustment:
165	// surcharges positive, discounts negative.
166	const policyModifiers = (policyBase: number, context: StepContext): number =>
167	  firstInsuranceSurcharge(policyBase) -
168	  loyaltyDiscount(context.customer, policyBase) -
169	  followUpDiscount(context.precedingQuotes, policyBase);
170	
171	const quotePremium = (items: Item[], context: StepContext): number => {
172	  const policyBase = policyBasePremium(items);
173	  return premiumRoundedInMHPCOsFavour(
174	    policyBase +
175	      policyModifiers(policyBase, context) +
176	      totalItemSurcharges(items) +
177	      PROCESSING_FEE,
178	  );
179	};
180	
181	const DEDUCTIBLE = 100;
182	const INSURANCE_VALUE_BY_TYPE: Record<string, number> = {
183	  sword: 1000,
184	  amulet: 600,
185	  staff: 800,
186	  potion: 400,
187	  rune: 250,
188	  moonstone: 250,
189	};
190	const CAP_MULTIPLE = 2;
191	
192	// And payouts in its own favour too: down.
193	const payoutRoundedInMHPCOsFavour = (payout: number): number =>
194	  Math.floor(payout);
195	
196	const insuranceSum = (items: Item[]): number =>
197	  items.reduce((sum, item) => sum + INSURANCE_VALUE_BY_TYPE[item.type], 0);
198	
199	const capOf = (items: Item[]): number => insuranceSum(items) * CAP_MULTIPLE;
200	
201	// Unrelated to the surcharge threshold above — see the note there.
202	const HALVED_REIMBURSEMENT_ENCHANTMENT_LEVEL = 8;
203	const HALVED_REIMBURSEMENT_RATE = 0.5;
204	
205	// Highly enchanted items are notoriously hard to appraise, so the MHPCO
206	// reimburses only half their damage.
207	const isEnchantedEnoughToHalve = (item: Item): boolean =>
208	  enchantmentLevelOf(item) >= HALVED_REIMBURSEMENT_ENCHANTMENT_LEVEL;
209	
210	const coveredAmount = (damage: Damage, item: Item): number =>
211	  isEnchantedEnoughToHalve(item)
212	    ? damage.amount * HALVED_REIMBURSEMENT_RATE
213	    : damage.amount;
214	
215	const reimbursement = (damage: Damage, item: Item): number =>
216	  coveredAmount(damage, item) - DEDUCTIBLE;
217	
218	// Both ways a single damage entry can be inadmissible. They are checked
219	// together, at the one place that already walks every entry, because they are
220	// the same kind of rule — an entry the policy cannot answer — and either one
221	// rejects the whole claim before any money is computed.
222	const rejectUnmatchedDamage = (damage: Damage, matchIndex: number): void => {
223	  if (matchIndex === -1) {
224	    throw new Error(`${damage.itemType} is not insured by this policy`);
225	  }
226	};
227	
228	const rejectNegativeDamage = (damage: Damage): void => {
229	  if (damage.amount < 0) {
230	    throw new Error(`damage amount ${damage.amount} is negative`);
231	  }
232	};
233	
234	// Each damage entry is answered by one insured item, which that entry uses up:
235	// two damaged swords need two insured swords. An entry with no item left to
236	// match rejects the whole claim.
237	//
238	// Pairing is kept separate from summing so that each half states one rule: this
239	// function owns "which item answers which damage, and is this entry one the
240	// policy can answer at all", and the caller owns "what does each pair pay".
241	const pairDamagesWithInsuredItems = (
242	  damages: Damage[],
243	  insuredItems: Item[],
244	): { damage: Damage; item: Item }[] => {
245	  const unclaimedItems = [...insuredItems];
246	  return damages.map((damage) => {
247	    const index = unclaimedItems.findIndex(
248	      ({ type }) => type === damage.itemType,
249	    );
250	    rejectUnmatchedDamage(damage, index);
251	    rejectNegativeDamage(damage);
252	    const [item] = unclaimedItems.splice(index, 1);
253	    return { damage, item };
254	  });
255	};
256	
257	const claimPayout = (incident: Incident, insuredItems: Item[]): number =>
258	  payoutRoundedInMHPCOsFavour(
259	    pairDamagesWithInsuredItems(incident.damages, insuredItems).reduce(
260	      (total, { damage, item }) => total + reimbursement(damage, item),
261	      0,
262	    ),
263	  );
264	
265	// A claim's `policy` is an index into the scenario's own steps, so it can miss
266	// in two ways: point past the end, or point at another claim. Both are the same
267	// mistake — a policy reference that no policy answers — and both are reported
268	// here rather than left to surface as a bare property access on `undefined`.
269	// (`steps[policy]` is typed `Step`, but only because `noUncheckedIndexedAccess`
270	// is off; at runtime an out-of-range index really is `undefined`.)
271	const insuredItemsOf = (steps: Step[], policy: number): Item[] => {
272	  const policyStep = steps.at(policy);
273	  if (policyStep === undefined || policyStep.op !== "quote") {
274	    throw new Error(`step ${policy} is not a quote`);
275	  }
276	  return policyStep.items;
277	};
278	
279	const runQuote = (items: Item[], context: StepContext): StepResult => ({
280	  premium: quotePremium(items, context),
281	});
282	
283	// A claim both reports its remaining cap and spends it: the cap it leaves
284	// behind is what the policy's next claim may draw on, so this writes the
285	// figure back into the running context as well as returning it.
286	const runClaim = (
287	  policy: number,
288	  incident: Incident,
289	  context: StepContext,
290	): StepResult => {
291	  const insuredItems = insuredItemsOf(context.steps, policy);
292	  const availableCap =
293	    context.remainingCapByPolicy.get(policy) ?? capOf(insuredItems);
294	  const payout = Math.min(claimPayout(incident, insuredItems), availableCap);
295	  const remainingCap = availableCap - payout;
296	  context.remainingCapByPolicy.set(policy, remainingCap);
297	  return { payout, remainingCap };
298	};
299	
300	const runStep = (step: Step, context: StepContext): StepResult =>
301	  step.op === "quote"
302	    ? runQuote(step.items, context)
303	    : runClaim(step.policy, step.incident, context);
304	
305	export const runScenario = (scenario: Scenario): ScenarioResult => {
306	  // Steps are run in order because later ones depend on earlier ones: a quote
307	  // makes every following quote a follow-up contract, and a claim spends cap
308	  // that every following claim on the same policy has to do without.
309	  const remainingCapByPolicy = new Map<number, number>();
310	  let precedingQuotes = 0;
311	  const results = scenario.steps.map((step) => {
312	    const result = runStep(step, {
313	      customer: scenario.customer,
314	      precedingQuotes,
315	      steps: scenario.steps,
316	      remainingCapByPolicy,
317	    });
318	    if (step.op === "quote") {
319	      precedingQuotes += 1;
320	    }
321	    return result;
322	  });
323	  return { results };
324	};
325

880	          },
881	        ],
882	      }),
883	      // Damage cannot be negative. Left unchecked this would pay out −300 G and
884	      // hand the customer 300 G of extra cap.
885	    ).toThrow(/-200/);
886	  });
887	});
888	
889	describe("MHPCO Claim Office — CLI", () => {
890	  it("reads a scenario from stdin and writes {results: [...]} to stdout in step order", () => {
891	    // The spec's own schema example, run as a real subprocess so the stdin →
892	    // stdout contract is exercised rather than simulated.
893	    const scenario = JSON.stringify({
894	      customer: { yearsWithMHPCO: 5 },
895	      steps: [
896	        {
897	          op: "quote",
898	          items: [
899	            { type: "amulet", material: "silver", enchantment: 2, cursed: false },
900	          ],
901	        },
902	        {
903	          op: "claim",
904	          policy: 0,
905	          incident: {
906	            cause: "fire",
907	            damages: [{ itemType: "amulet", amount: 200 }],
908	          },
909	        },
910	      ],
911	    });
912	
913	    const stdout = execFileSync("npx", ["tsx", "src/cli.ts"], {
914	      input: scenario,
915	      encoding: "utf8",
916	    });
917	
918	    // Quote: 60 G base − 12 G loyalty + 6 G first insurance + 5 G fee = 59 G.
919	    // Claim: 200 − 100 deductible = 100 G; cap 2 × 600 = 1200, so 1100 G remains.
920	    expect(JSON.parse(stdout)).toEqual({
921	      results: [{ premium: 59 }, { payout: 100, remainingCap: 1100 }],
922	    });
923	  });
924	  it.todo("exits with a non-zero status and writes an error description to stderr on an invalid scenario");
925	});
